    private fun requestCamera(){
        if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){retry.visibility=View.GONE;preview.post{bindCamera()}}
        else if(retry.text.toString()=="Open app settings"){startActivity(Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:$packageName")))}
        else{status.text="Camera access is needed to scan. Gallery and the other scanner are available.";retry.visibility=View.VISIBLE
            requestPermissions(arrayOf(Manifest.permission.CAMERA),701)}
    }
    override fun onRequestPermissionsResult(requestCode:Int,permissions:Array<out String>,results:IntArray){
        super.onRequestPermissionsResult(requestCode,permissions,results)
        if(requestCode==701){if(results.firstOrNull()==PackageManager.PERMISSION_GRANTED){retry.visibility=View.GONE;preview.post{bindCamera()}}
            else{status.text="Camera access was denied. Allow it in app settings, or choose Gallery / Other scanner.";retry.visibility=View.VISIBLE;retry.text=if(shouldShowRequestPermissionRationale(Manifest.permission.CAMERA))"Allow camera" else "Open app settings"}}
    }
    private fun bindCamera(){
        if(isFinishing||isDestroyed||busy||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||preview.width==0||preview.height==0)return
        val rotation=preview.display?.rotation?:Surface.ROTATION_0
        if(running&&boundRotation==rotation&&boundWidth==preview.width&&boundHeight==preview.height&&camera!=null)return
        val token=++session
        val future=ProcessCameraProvider.getInstance(this)
        future.addListener({
            if(isFinishing||isDestroyed||token!=session)return@addListener
            try{
                val p=future.get();provider=p;p.unbindAll()
                val live=Preview.Builder().setTargetAspectRatio(AspectRatio.RATIO_4_3).setTargetRotation(rotation).build()
                val still=ImageCapture.Builder().setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY).setTargetAspectRatio(AspectRatio.RATIO_4_3).setTargetRotation(rotation).build()
                val frames=ImageAnalysis.Builder().setTargetResolution(android.util.Size(640,480)).setTargetRotation(rotation).setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build()
                live.setSurfaceProvider(preview.surfaceProvider)
                val group=UseCaseGroup.Builder().addUseCase(live).addUseCase(still).addUseCase(frames)
                preview.viewPort?.let{group.setViewPort(it)}?:throw IllegalStateException("Preview not ready")
                camera=p.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,group.build())
                capture=still;analysis=frames;boundRotation=rotation;boundWidth=preview.width;boundHeight=preview.height;running=true;latest=null;stability.reset()
                frames.setAnalyzer(analyzer){image->analyze(image,token)}
                torchOn=false;torch.text="Torch off";torch.isEnabled=camera?.cameraInfo?.hasFlashUnit()==true
                zoom.progress=0;zoom.isEnabled=true;retry.visibility=View.GONE
                status.text="Keep the whole page in view. Tap Capture anytime.";updateControls()
            }catch(_:Exception){running=false;capture=null;shutter.isEnabled=false;torch.isEnabled=false;zoom.isEnabled=false;status.text="Live camera unavailable on this device. Use Gallery or Other scanner."}
        },ContextCompat.getMainExecutor(this))
    }
    private fun analyze(image:ImageProxy,token:Int){
        try{
            val now=SystemClock.elapsedRealtime();if(now-lastAnalysis<200)return;lastAnalysis=now
            val rect=image.cropRect;val plane=image.planes[0]
            val gray=ScanDetector.sample(plane.buffer,plane.rowStride,plane.pixelStride,rect.left,rect.top,rect.width(),rect.height(),image.imageInfo.rotationDegrees)
            val candidate=ScanDetector.detect(gray)
            runOnUiThread{
                if(!running||!resumed||busy||isFinishing||isDestroyed||token!=session)return@runOnUiThread
                val result=stability.update(candidate,now);latest=result.candidate;latestAt=now
                overlay.update(result.candidate?.corners,result.stable)
                status.text=when{pages.size>=30->"30 pages ready. Review and save before adding more."
                    result.candidate==null->"No clear page outline. Manual Capture is available."
                    autoMode&&result.ready->"Page steady — capturing…"
                    autoMode&&result.stable->"Lift the page out of view before the next auto capture."
                    autoMode->"Hold steady. Improve light or use manual Capture."
                    else->"Page outline found. Tap Capture or turn on Auto."}
                if(autoMode&&result.ready&&pages.size<30)takePhoto(true)
            }
        }catch(_:Exception){/* An uncertain/malformed frame never disables manual capture. */}
        finally{image.close()}
    }
    private fun takePhoto(automatic:Boolean){
        val still=capture?:return;if(busy||!running||!resumed||pages.size>=30)return
        busy=true;updateControls();status.text="Saving original page…"
        val proposed=if(automatic&&SystemClock.elapsedRealtime()-latestAt<400)latest else null
        stability.captured();overlay.update(null,false)
        val app=applicationContext
        ScanWork.executor.execute{
            try{
                require(store.folder.usableSpace>64L*1024*1024){"Free storage before capturing."}
                val output=store.newCapture()
                runOnUiThread{
                    if(isFinishing||isDestroyed){ScanWork.executor.execute{store.finishCapture(false)};return@runOnUiThread}
                    try { still.takePicture(ImageCapture.OutputFileOptions.Builder(output).build(),ContextCompat.getMainExecutor(this),object:ImageCapture.OnImageSavedCallback{
                        override fun onImageSaved(result:ImageCapture.OutputFileResults){
                            ScanWork.executor.execute{
                                var saved=emptyList<String>();var warning=false
                                try{
                                    saved=ScanDraftStore(app).finishCapture(true)
                                    if(proposed!=null){
                                        val bounds=StudioImages.load(saved.last(),160)
                                        val ratio=bounds.width.toDouble()/bounds.height;bounds.recycle()
                                        // ViewPort aligns streams; refuse a stale/aspect-mismatched crop rather than cut content.
                                        if(abs(ratio/proposed.ratio-1)<.035){
                                            try{saved=ScanDraftStore(app).edit(listOf(saved.last()),"original",null,proposed.corners)}catch(_:Exception){warning=true}
                                        }else warning=true
                                    }
                                    val completed=saved
                                    runOnUiThread{if(!isDestroyed){pages=completed;busy=false;updatePages();status.text=if(warning)"Photo saved. Check and adjust its corners in review." else "Page saved. Lift it away before the next auto capture."}}
                                }catch(_:Exception){runOnUiThread{if(!isDestroyed){busy=false;status.text="Could not finish this page. Earlier pages are safe; retry or review.";updateControls()}}}
                            }
                        }
                        override fun onError(error:ImageCaptureException){ScanWork.executor.execute{try{store.finishCapture(false)}catch(_:Exception){};runOnUiThread{if(!isDestroyed){busy=false;status.text="Capture failed. Earlier pages are safe.";updateControls()}}}}
                    }) } catch(_:Exception) {
                        ScanWork.executor.execute { try { store.finishCapture(false) } catch(_:Exception) {}
                            runOnUiThread { if(!isDestroyed) { busy=false;status.text="Capture was interrupted. Earlier pages are safe.";updateControls() } }
                        }
                    }
                }
            }catch(_:Exception){runOnUiThread{if(!isDestroyed){busy=false;status.text="Could not start this page. Review your saved pages or free storage.";updateControls()}}}
        }
    }
    private fun updateControls(){shutter.isEnabled=running&&!busy&&pages.size<30;done.isEnabled=!busy;auto.isEnabled=!busy;torch.isEnabled=!busy&&camera?.cameraInfo?.hasFlashUnit()==true;zoom.isEnabled=running&&!busy}
    private fun updatePages(){
        done.text="Review (${pages.size})";updateControls();if(boundRotation<0&&resumed)preview.post{bindCamera()};strip.removeAllViews()
        // Only bounded thumbnails are decoded, serially; stale callbacks cannot attach to a new strip.
        val current=pages.toList();val generation=++thumbnailGeneration
        current.forEachIndexed{index,path->
            val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;contentDescription="Page ${index+1}. Review saved pages.";setOnClickListener{finishReview()}}
            val image=ImageView(this).apply{scaleType=ImageView.ScaleType.FIT_CENTER};box.addView(image,LinearLayout.LayoutParams(dp(48),dp(44)))
            box.addView(label("${index+1}").apply{textSize=11f;setPadding(0,0,0,0)})
            strip.addView(box,LinearLayout.LayoutParams(dp(60),dp(68)))
            ScanWork.executor.execute{try{val bitmap=StudioImages.load(path,128);runOnUiThread{if(isDestroyed||generation!=thumbnailGeneration)bitmap.recycle()else image.setImageBitmap(bitmap)}}catch(_:Exception){}}
        }
    }
    private var thumbnailGeneration=0
    private fun toggleTorch(){if(busy)return;val c=camera?:return;if(!c.cameraInfo.hasFlashUnit())return
        val next=!torchOn;val task=c.cameraControl.enableTorch(next)
        task.addListener({try{task.get();torchOn=next;torch.text=if(next)"Torch on" else "Torch off";stability.reset()}catch(_:Exception){status.text="Torch could not be changed on this device."}},ContextCompat.getMainExecutor(this))}
    private fun finishReview(action:String="review"){if(busy){status.text="Finishing this page. Please wait.";return};setResult(RESULT_OK,Intent().putExtra("action",action));finish()}
    override fun onConfigurationChanged(newConfig:Configuration){super.onConfigurationChanged(newConfig);applyLayout();boundRotation=-1;running=false;updateControls();stability.reset();latest=null;preview.post{bindCamera()}}
    override fun onResume(){super.onResume();resumed=true;if(!busy&&checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)preview.post{bindCamera()}}
    override fun onPause(){resumed=false;super.onPause();latest=null;stability.reset();overlay.update(null,false);camera?.cameraControl?.enableTorch(false);torchOn=false;torch.text="Torch off"}
    override fun onDestroy(){session++;thumbnailGeneration++;running=false;analysis?.clearAnalyzer();provider?.unbindAll();analyzer.shutdown();super.onDestroy()}
}

class ScanOutline(context:android.content.Context):View(context){
    private var corners:List<Double>?=null;private var stable=false
    fun update(points:List<Double>?,steady:Boolean){corners=points;stable=steady;invalidate()}
    override fun onDraw(canvas:Canvas){super.onDraw(canvas);val q=corners?:return
        val path=Path().apply{moveTo((q[0]*width).toFloat(),(q[1]*height).toFloat());for(i in 1..3)lineTo((q[i*2]*width).toFloat(),(q[i*2+1]*height).toFloat());close()}
        val color=if(stable)Color.rgb(89,231,184)else Color.rgb(255,218,115)
        canvas.drawPath(path,Paint(Paint.ANTI_ALIAS_FLAG).apply{this.color=color;style=Paint.Style.STROKE;strokeWidth=3*resources.displayMetrics.density})
        for(i in 0..3)canvas.drawCircle((q[i*2]*width).toFloat(),(q[i*2+1]*height).toFloat(),5*resources.displayMetrics.density,Paint(Paint.ANTI_ALIAS_FLAG).apply{this.color=color})
    }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.Intent
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import java.util.concurrent.Executors

/** Process-lifetime disk queue. Capture callbacks may finish after the Activity is recreated. */
object ScanWork { val executor = Executors.newSingleThreadExecutor() }

class HyzenLiveScanner(private val activity:MainActivity,messenger:BinaryMessenger) {
    private var pending:MethodChannel.Result?=null
    private val channel=MethodChannel(messenger,"com.hyzen.pharmd/live_scanner")
    init{channel.setMethodCallHandler{call,result->
        if(call.method!="scan"){result.notImplemented();return@setMethodCallHandler}
        if(active){result.error("busy","Finish the current scan first.",null);return@setMethodCallHandler}
        active=true;pending=result
        try{activity.startActivityForResult(Intent(activity,HyzenScanActivity::class.java),REQUEST)}
        catch(_:Exception){active=false;pending=null;result.error("camera","Camera preview unavailable. Use the other scanner or gallery.",null)}
    }}
    fun receive(code:Int,resultCode:Int,data:Intent?):Boolean{
        if(code!=REQUEST)return false
        active=false;val result=pending;pending=null
        ScanWork.executor.execute{
            try{val pages=ScanDraftStore(activity.applicationContext).recover()
                activity.runOnUiThread{result?.success(mapOf("pages" to pages,"action" to (data?.getStringExtra("action")?:"review")))}}
            catch(_:Exception){activity.runOnUiThread{result?.error("camera","Could not restore the scan. Earlier pages remain saved.",null)}}
        }
        return true
    }
    fun close(){pending=null}
    companion object{const val REQUEST=8894;@Volatile var active=false;private set}
}

