/** Local PDF operations. Pages are rasterized so input documents are never modified. */
class StudioPdfEngine(private val activity: MainActivity, engine: FlutterEngine) {
    private val worker = Executors.newSingleThreadExecutor()
    private val documentOps = StudioDocumentOps(activity)

    init {
        MethodChannel(engine.dartExecutor.binaryMessenger, "com.hyzen.pharmd/pdf_studio")
            .setMethodCallHandler { call, result ->
                worker.execute {
                    try {
                        val answer: Any = when (call.method) {
                            "pageCount" -> {
                                val path = call.argument<String>("path") ?: error("Missing PDF path")
                                ParcelFileDescriptor.open(File(path), ParcelFileDescriptor.MODE_READ_ONLY).use { fd ->
                                    PdfRenderer(fd).use { it.pageCount }
                                }
                            }
                            "compose" -> {
                                val pages = call.argument<List<Map<String, Any?>>>("pages") ?: error("No pages selected")
                                if (call.argument<Boolean>("flatten") == true) compose(pages) else documentOps.compose(pages)
                            }
                            "protect" -> documentOps.protect(call.argument<String>("path") ?: error("Missing PDF"), call.argument<String>("password") ?: error("Missing password"))
                            "ocr" -> documentOps.ocr(call.argument<String>("path") ?: error("Missing PDF"))
                            "compress" -> documentOps.compress(call.argument<String>("path") ?: error("Missing PDF"), call.argument<String>("preset") ?: "balanced")
                            "richDocument" -> StudioRichWriter(activity).write(call.argument<List<Map<String,Any?>>>("blocks") ?: error("Missing document"),call.argument<String>("format") ?: "pdf")
                            "imagesToPdf" -> {
                                check(!HyzenLiveScanner.active) { "Finish the live camera before exporting." }
                                val paths = call.argument<List<String>>("paths") ?: error("No images selected")
                                if (call.argument<Boolean>("scanDraft") == true) ScanDraftStore(activity).exportPdf(paths, call.argument<Boolean>("highQuality") == true, call.argument<String>("paper") ?: "a4", call.argument<String>("orientation") ?: "auto", call.argument<Int>("margin") ?: 16) else documentOps.imagesToPdf(paths, paper = call.argument<String>("paper") ?: "a4", orientation = call.argument<String>("orientation") ?: "auto", margin = call.argument<Int>("margin") ?: 16)
                            }
                            "textToPdf" -> textToPdf(call.argument<String>("text") ?: "")
                            "textToDocx" -> textToDocx(call.argument<String>("text") ?: "")
                            "textFile" -> {
                                File.createTempFile("studio_note_", ".txt", activity.cacheDir).apply {
                                    writeText(call.argument<String>("text") ?: "")
                                }.absolutePath
                            }
                            "readText" -> {
                                val source = File(call.argument<String>("path") ?: error("Missing document"))
                                require(source.length() <= 2_000_000L) { "Text file is too large." }
                                source.readText(Charsets.UTF_8)
                            }
                            "pagesToImages" -> pagesToImages(
                                call.argument<String>("path") ?: error("Missing PDF"),
                                call.argument<String>("format") ?: "png"
                            )
                            "renderPage" -> renderPage(
                                call.argument<String>("path") ?: error("Missing PDF"),
                                call.argument<Int>("index") ?: 0,
                                call.argument<Int>("maxEdge") ?: 1800
                            )
                            "getEditState" -> stateFile(call.argument<String>("path") ?: error("Missing state")).readText()
                            "setEditState" -> {
                                val content = call.argument<String>("json") ?: error("Missing annotation state")
                                require(content.length <= 500_000) { "Too many annotations" }
                                val target = stateFile(call.argument<String>("path") ?: error("Missing state"))
                                val partial = File(target.parentFile, "${target.name}.part")
                                try {
                                    partial.writeText(content)
                                    require(partial.renameTo(target)) { "Could not save annotations" }
                                } finally { if (partial.exists()) partial.delete() }
                                true
                            }
                            else -> {
                                activity.runOnUiThread { result.notImplemented() }
                                return@execute
                            }
                        }
                        activity.runOnUiThread { result.success(answer) }
                    } catch (_: OutOfMemoryError) {
                        activity.runOnUiThread { result.error("pdf_memory", "Not enough memory. Save fewer pages; your draft is safe.", null) }
                    } catch (e: Exception) {
                        activity.runOnUiThread {
                            result.error("pdf_studio", e.message ?: "PDF operation failed", null)
                        }
                    }
                }
            }
    }

    private fun output(): File = File.createTempFile("studio_", ".pdf", activity.cacheDir)

    private fun compose(pages: List<Map<String, Any?>>): String {
        require(pages.isNotEmpty() && pages.size <= 150) { "Select 1–150 pages." }
        val destination = output()
        val document = PdfDocument()
        val inputs = mutableMapOf<String, Pair<ParcelFileDescriptor, PdfRenderer>>()
        try {
            pages.forEachIndexed { position, spec ->
                if (spec["blank"] == true) {
                    val blank = document.startPage(PdfDocument.PageInfo.Builder(595, 842, position + 1).create())
                    blank.canvas.drawColor(Color.WHITE)
                    document.finishPage(blank)
                    return@forEachIndexed
                }
                val source = File(spec["path"] as? String ?: error("Missing source"))
                val index = (spec["page"] as? Number)?.toInt() ?: error("Missing page index")
                val rotation = ((spec["rotation"] as? Number)?.toInt() ?: 0).rem(360)
                require(rotation == 0 || rotation == 90 || rotation == 180 || rotation == 270) { "Invalid rotation" }
                val renderer = inputs.getOrPut(source.canonicalPath) {
                    val fd = ParcelFileDescriptor.open(source, ParcelFileDescriptor.MODE_READ_ONLY)
                    try { fd to PdfRenderer(fd) }
                    catch (e: Exception) { fd.close(); throw e }
                }.second
                        require(index in 0 until renderer.pageCount) { "Page out of range" }
                        renderer.openPage(index).use { page ->
                            val sideways = rotation == 90 || rotation == 270
                            val width = if (sideways) page.height else page.width
                            val height = if (sideways) page.width else page.height
                            val scale = minOf(2f, 2000f / maxOf(page.width, page.height))
                            val bitmap = Bitmap.createBitmap(
                                maxOf(1, (page.width * scale).toInt()),
                                maxOf(1, (page.height * scale).toInt()), Bitmap.Config.ARGB_8888
                            )
                            try {
                                bitmap.eraseColor(Color.WHITE)
                                page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                                val info = PdfDocument.PageInfo.Builder(width, height, position + 1).create()
                                val target = document.startPage(info)
                                val canvas = target.canvas
                                canvas.drawColor(Color.WHITE)
                                canvas.save()
                                when (rotation) {
                                    90 -> { canvas.translate(width.toFloat(), 0f); canvas.rotate(90f) }
                                    180 -> { canvas.translate(width.toFloat(), height.toFloat()); canvas.rotate(180f) }
                                    270 -> { canvas.translate(0f, height.toFloat()); canvas.rotate(270f) }
                                }
                                canvas.drawBitmap(bitmap, null, RectF(0f, 0f, page.width.toFloat(), page.height.toFloat()), Paint(Paint.FILTER_BITMAP_FLAG))
                                canvas.restore()
                                @Suppress("UNCHECKED_CAST")
                                val marks = spec["annotations"] as? List<Map<String, Any?>> ?: emptyList()
                                paintAnnotations(canvas, marks, width.toFloat(), height.toFloat())
                                document.finishPage(target)
                            } finally { bitmap.recycle() }
                        }
            }
            destination.outputStream().use { document.writeTo(it) }
            return destination.absolutePath
        } catch (e: Exception) {
            destination.delete()
            throw e
        } finally {
            document.close()
            inputs.values.forEach { (fd, renderer) ->
                try { renderer.close() } finally { fd.close() }
            }
        }
    }

    private fun imagesToPdf(paths: List<String>): String {
        require(paths.isNotEmpty() && paths.size <= 50) { "Choose 1–50 images." }
        val destination = output()
        val document = PdfDocument()
        try {
            paths.forEachIndexed { index, path ->
                val bitmap = StudioImages.load(path)
                try {
                    val portrait = bitmap.height >= bitmap.width
                    val width = if (portrait) 595 else 842
                    val height = if (portrait) 842 else 595
                    val page = document.startPage(PdfDocument.PageInfo.Builder(width, height, index + 1).create())
                    page.canvas.drawColor(Color.WHITE)
                    val factor = minOf((width - 40f) / bitmap.width, (height - 40f) / bitmap.height)
                    val w = bitmap.width * factor
                    val h = bitmap.height * factor
                    page.canvas.drawBitmap(bitmap, null, RectF((width - w) / 2, (height - h) / 2, (width + w) / 2, (height + h) / 2), Paint(Paint.FILTER_BITMAP_FLAG))
                    document.finishPage(page)
                } finally { bitmap.recycle() }
            }
            destination.outputStream().use { document.writeTo(it) }
            return destination.absolutePath
        } catch (e: Exception) { destination.delete(); throw e }
        finally { document.close() }
    }

    private fun textToPdf(text: String): String {
        require(text.length <= 200_000) { "Document is too long." }
        val destination = output()
        val document = PdfDocument()
        val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = Color.BLACK; textSize = 12f }
        try {
            val lines = mutableListOf<String>()
            text.replace("\r\n", "\n").split('\n').forEach { paragraph ->
                var line = ""
                paragraph.split(' ').forEach { word ->
                    val next = if (line.isEmpty()) word else "$line $word"
                    if (paint.measureText(next) > 510f && line.isNotEmpty()) { lines.add(line); line = word }
                    else line = next
                }
                lines.add(line)
            }
            require(lines.size <= 5000) { "Document is too long." }
            lines.chunked(48).forEachIndexed { i, chunk ->
                val page = document.startPage(PdfDocument.PageInfo.Builder(595, 842, i + 1).create())
                page.canvas.drawColor(Color.WHITE)
                chunk.forEachIndexed { row, line -> page.canvas.drawText(line.take(400), 42f, 48f + row * 16f, paint) }
                document.finishPage(page)
            }
            destination.outputStream().use { document.writeTo(it) }
            return destination.absolutePath
        } catch (e: Exception) { destination.delete(); throw e }
        finally { document.close() }
    }

    private fun textToDocx(text: String): String {
        require(text.length <= 200_000) { "Document is too long." }
        val destination = File.createTempFile("studio_document_", ".docx", activity.cacheDir)
        fun escape(value: String): String = value.replace("&", "&amp;")
            .replace("<", "&lt;").replace(">", "&gt;")
            .replace("\"", "&quot;").replace("'", "&apos;")
        val paragraphs = text.replace("\r\n", "\n").split('\n').joinToString("") { line ->
            "<w:p><w:r><w:t xml:space=\"preserve\">${escape(line.filter { it == '\t' || it >= ' ' })}</w:t></w:r></w:p>"
        }
        try {
            ZipOutputStream(destination.outputStream().buffered()).use { zip ->
                fun entry(name: String, xml: String) {
                    zip.putNextEntry(ZipEntry(name))
                    zip.write(xml.toByteArray(Charsets.UTF_8))
                    zip.closeEntry()
                }
                entry("[Content_Types].xml", """<?xml version="1.0" encoding="UTF-8"?>
                    <Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
                    <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
                    <Default Extension="xml" ContentType="application/xml"/>
                    <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
                    </Types>""".trimIndent())
                entry("_rels/.rels", """<?xml version="1.0" encoding="UTF-8"?>
                    <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
                    <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
                    </Relationships>""".trimIndent())
                entry("word/document.xml", """<?xml version="1.0" encoding="UTF-8"?>
                    <w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
                    <w:body>$paragraphs<w:sectPr/></w:body></w:document>""".trimIndent())
            }
            return destination.absolutePath
        } catch (e: Exception) { destination.delete(); throw e }
    }

    private fun pagesToImages(path: String, format: String): String {
        require(format == "png" || format == "jpg") { "Choose PNG or JPG." }
        val archive = File.createTempFile("studio_pages_", ".zip", activity.cacheDir)
        try {
            ParcelFileDescriptor.open(File(path), ParcelFileDescriptor.MODE_READ_ONLY).use { fd ->
                PdfRenderer(fd).use { renderer ->
                    require(renderer.pageCount <= 150) { "Export up to 150 pages." }
                    ZipOutputStream(archive.outputStream().buffered()).use { zip ->
                        for (index in 0 until renderer.pageCount) {
                            renderer.openPage(index).use { page ->
                                val factor = minOf(2f, 2000f / maxOf(page.width, page.height))
                                val bitmap = Bitmap.createBitmap(
                                    maxOf(1, (page.width * factor).toInt()),
                                    maxOf(1, (page.height * factor).toInt()), Bitmap.Config.ARGB_8888
                                )
                                try {
                                    bitmap.eraseColor(Color.WHITE)
                                    page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                                    zip.putNextEntry(ZipEntry("page_${(index + 1).toString().padStart(3, '0')}.$format"))
                                    bitmap.compress(if (format == "png") Bitmap.CompressFormat.PNG else Bitmap.CompressFormat.JPEG, 85, zip)
                                    zip.closeEntry()
                                } finally { bitmap.recycle() }
                            }
                        }
                    }
                }
            }
            return archive.absolutePath
        } catch (e: Exception) { archive.delete(); throw e }
    }

    private fun stateFile(path: String): File {
        val root = File(activity.filesDir, "pdf_studio/state").canonicalFile
        val target = File(path).canonicalFile
        require(target.parentFile == root && target.name.endsWith("_state.json") && target.isFile) {
            "Annotation state is unavailable"
        }
        return target
    }

    private fun renderPage(path: String, index: Int, maxEdge: Int = 1800): Map<String, Any> =
        PdfPagePreviewRenderer.render(path, index, maxEdge)

    private fun paintAnnotations(canvas: Canvas, marks: List<Map<String, Any?>>, width: Float, height: Float) {
        for (mark in marks.take(200)) {
            val type = mark["tool"] as? String ?: continue
            val raw = mark["points"] as? List<*> ?: continue
            val points = raw.mapNotNull { pair ->
                val values = pair as? List<*> ?: return@mapNotNull null
                if (values.size != 2) return@mapNotNull null
                val x = (values[0] as? Number)?.toFloat() ?: return@mapNotNull null
                val y = (values[1] as? Number)?.toFloat() ?: return@mapNotNull null
                if (!x.isFinite() || !y.isFinite()) return@mapNotNull null
                (x.coerceIn(0f, 1f) * width) to (y.coerceIn(0f, 1f) * height)
            }
            if (points.isEmpty()) continue
            val color = (mark["color"] as? Number)?.toInt() ?: Color.rgb(103, 49, 210)
            val stroke = ((mark["stroke"] as? Number)?.toFloat() ?: 3f).coerceIn(1f, 32f)
            val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                this.color = if (type == "highlight") (color and 0x00FFFFFF) or 0x66000000 else color
                style = Paint.Style.STROKE
                strokeWidth = if (type == "highlight") stroke * 5f else stroke
                strokeCap = Paint.Cap.ROUND
                strokeJoin = Paint.Join.ROUND
            }
            val first = points.first()
            val last = points.last()
            when (type) {
                "ink", "highlight", "underline", "strike", "arrow" -> {
                    val line = Path().apply {
                        moveTo(first.first, first.second)
                        points.drop(1).forEach { lineTo(it.first, it.second) }
                    }
                    canvas.drawPath(line, paint)
                    if(type=="arrow") {
                        val angle=kotlin.math.atan2(last.second-first.second,last.first-first.first)
                        val head=maxOf(10f,stroke*4)
                        canvas.drawLine(last.first,last.second,last.first-head*kotlin.math.cos(angle-.5f),last.second-head*kotlin.math.sin(angle-.5f),paint)
                        canvas.drawLine(last.first,last.second,last.first-head*kotlin.math.cos(angle+.5f),last.second-head*kotlin.math.sin(angle+.5f),paint)
                    }
                }
                "rectangle" -> canvas.drawRect(minOf(first.first, last.first), minOf(first.second, last.second),
                    maxOf(first.first, last.first), maxOf(first.second, last.second), paint)
                "circle" -> canvas.drawOval(RectF(minOf(first.first, last.first), minOf(first.second, last.second),
                    maxOf(first.first, last.first), maxOf(first.second, last.second)), paint)
                "text", "signature", "note" -> {
                    val label = (mark["text"] as? String ?: "").take(90)
                    paint.style = Paint.Style.FILL
                    paint.textSize = if (type == "signature") 24f else 14f
                    if (type == "signature") paint.typeface = Typeface.create(Typeface.SERIF, Typeface.ITALIC)
                    canvas.drawText(label, first.first, first.second + paint.textSize, paint)
                }
            }
        }
    }

    fun close() { worker.shutdown() }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.provider.OpenableColumns
import android.graphics.BitmapFactory
import android.graphics.Bitmap
import android.graphics.Matrix
import android.media.ExifInterface
import java.io.File
import androidx.core.content.FileProvider
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.ByteArrayOutputStream
import java.util.concurrent.Executors

class MainActivity : FlutterActivity() {
    private var externalFiles: HyzenExternalFiles? = null
    private var studioPdfEngine: StudioPdfEngine? = null
    private var documentScanner: HyzenDocumentScanner? = null
    private var liveScanner: HyzenLiveScanner? = null
    private var cameraCapture: HyzenCameraCapture? = null
    private val pickCode = 8711
    private val saveCode = 8712
    private val imageCode = 8713
    private val studioPickCode = 8714
    private var exportPath: String? = null
    private var dataSelection=false
    private var pending: MethodChannel.Result? = null
    private var templateText: String? = null
    private val fileWorker = Executors.newSingleThreadExecutor()

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        HyzenUpdater(this, flutterEngine.dartExecutor.binaryMessenger)
        externalFiles = HyzenExternalFiles(this, flutterEngine.dartExecutor.binaryMessenger)
        studioPdfEngine = StudioPdfEngine(this, flutterEngine)
        documentScanner = HyzenDocumentScanner(this, flutterEngine.dartExecutor.binaryMessenger)
        liveScanner = HyzenLiveScanner(this, flutterEngine.dartExecutor.binaryMessenger)
        cameraCapture = HyzenCameraCapture(this, flutterEngine.dartExecutor.binaryMessenger)
        externalFiles?.receive(intent)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "com.hyzen.pharmd/csv_files")
            .setMethodCallHandler { call, result ->
                if (pending != null) {
                    result.error("busy", "Finish the current file selection first.", null)
                    return@setMethodCallHandler
                }
                when (call.method) {
                    "pickCsvFiles", "pickDataFiles" -> {
                        dataSelection=call.method=="pickDataFiles"
                        pending = result
                        try {
                            val intent = Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                                addCategory(Intent.CATEGORY_OPENABLE)
                                type = "*/*"
                                putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                                putExtra(Intent.EXTRA_MIME_TYPES, arrayOf("text/csv", "text/comma-separated-values", "application/csv", "application/vnd.ms-excel", "text/plain", "application/octet-stream", "application/json", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
                            }
                            startActivityForResult(intent, pickCode)
                        } catch (e: Exception) { finishError("picker", "Could not open the file picker.") }
                    }
                    "saveCsvTemplate" -> {
                        pending = result
                        templateText = call.argument<String>("text")
                        try {
                            startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
                                addCategory(Intent.CATEGORY_OPENABLE)
                                type = "text/csv"
                                putExtra(Intent.EXTRA_TITLE, "hyzen_bulk_import_template.csv")
                            }, saveCode)
                        } catch (e: Exception) { finishError("save", "Could not choose a save location.") }
                    }
                    "pickImage" -> {
                        pending=result
                        try { startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                            addCategory(Intent.CATEGORY_OPENABLE);type="image/*"
                            putExtra(Intent.EXTRA_MIME_TYPES,arrayOf("image/jpeg","image/png","image/webp"))
                        },imageCode) } catch (e:Exception){finishError("picker","Could not open photos.")}
                    }
                    "pickStudioFiles" -> {
                        pending = result
                        try {
                            startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                                addCategory(Intent.CATEGORY_OPENABLE)
                                type = "*/*"
                                putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                                putExtra(Intent.EXTRA_MIME_TYPES, arrayOf(
                                    "application/pdf", "image/jpeg", "image/png", "image/webp", "text/plain", "text/markdown", "application/rtf", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                                ))
                            }, studioPickCode)
                        } catch (e: Exception) { finishError("picker", "Could not open documents.") }
                    }
                    "saveFile", "exportFile" -> {
                        pending=result
                        templateText=call.argument<String>("text")
                        exportPath=call.argument<String>("path")
                        try {startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
                            addCategory(Intent.CATEGORY_OPENABLE)
                            type=call.argument<String>("mime") ?: "text/plain"
                            putExtra(Intent.EXTRA_TITLE,call.argument<String>("name") ?: "hyzen_export.txt")
                        },saveCode)}catch(e:Exception){finishError("save","Could not save the file.")}
                    }
                    "shareFile" -> {
                        val path = call.argument<String>("path")
                        val name = call.argument<String>("name") ?: "document"
                        val mime = call.argument<String>("mime") ?: "application/octet-stream"
                        if (path.isNullOrBlank() || !File(path).isFile) {
                            result.error("share", "This document is no longer available.", null)
                        } else {
                            fileWorker.execute {
                                var shared: File? = null
                                try {
                                    val folder = File(cacheDir, "hyzen_shares").apply { mkdirs() }
                                    val safeName = name.replace(Regex("[^A-Za-z0-9._-]"), "_").take(120)
                                    val shareCopy = File(folder, "${System.currentTimeMillis()}_$safeName")
                                    shared = shareCopy
                                    File(path).inputStream().use { input ->
                                        shareCopy.outputStream().use { output -> input.copyTo(output) }
                                    }
                                    val uri = FileProvider.getUriForFile(this, "$packageName.updates", shareCopy)
                                    val send = Intent(Intent.ACTION_SEND).apply {
                                        type = mime
                                        putExtra(Intent.EXTRA_STREAM, uri)
                                        putExtra(Intent.EXTRA_TITLE, name)
                                        clipData = android.content.ClipData.newRawUri(name, uri)
                                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                                    }
                                    runOnUiThread {
                                        try {
                                            startActivity(Intent.createChooser(send, "Share $name"))
                                            result.success(true)
                                        } catch (e: Exception) {
                                            shared?.delete()
                                            result.error("share", "No app can share this file.", null)
                                        }
                                    }
                                } catch (e: Exception) {
                                    shared?.delete()
                                    runOnUiThread { result.error("share", "Could not prepare this file to share.", null) }
                                }
                            }
                        }
                    }
                    else -> result.notImplemented()
                }
            }
    }
    private fun finishError(code: String, message: String) {
        val result = pending
        pending = null
        templateText = null
        exportPath = null
        result?.error(code, message, null)
    }
    private fun fileName(uri: Uri): String {
        contentResolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor ->
            if (cursor.moveToFirst()) return cursor.getString(0) ?: "import.csv"
        }
        return uri.lastPathSegment ?: "import.csv"
    }
    @Deprecated("Activity result bridge retained for Flutter file picker")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (liveScanner?.receive(requestCode, resultCode, data) == true) return
        if (cameraCapture?.receive(requestCode, resultCode) == true) return
        if (documentScanner?.receive(requestCode, resultCode, data) == true) return
        if (requestCode != pickCode && requestCode != saveCode && requestCode != imageCode && requestCode != studioPickCode) return
        val result = pending ?: return
        if (resultCode != Activity.RESULT_OK) {
            pending = null
            templateText = null
        exportPath = null
            result.success(if (requestCode == pickCode || requestCode == studioPickCode) emptyList<Map<String, Any>>() else if(requestCode==imageCode)null else false)
            return
        }
        val text = templateText ?: ""
        val sourcePath=exportPath
        fileWorker.execute {
            try {
                val response: Any
                if (requestCode == saveCode) {
                    val uri = data?.data ?: throw IllegalStateException("No destination selected.")
                    val stream = contentResolver.openOutputStream(uri, "wt") ?: throw IllegalStateException("Could not open destination.")
                    stream.use { target ->
                        if(sourcePath!=null)File(sourcePath).inputStream().use{it.copyTo(target)}
                        else target.write(text.toByteArray(Charsets.UTF_8))
                    }
                    response = true
                } else if (requestCode == studioPickCode) {
                    val uris = mutableListOf<Uri>()
                    val clips = data?.clipData
                    if (clips != null) {
                        if (clips.itemCount > 20) throw IllegalStateException("Choose at most 20 files.")
                        for (i in 0 until clips.itemCount) uris.add(clips.getItemAt(i).uri)
                    } else data?.data?.let { uris.add(it) }
                    response = uris.map { uri ->
                        val name = fileName(uri)
                        val extension = name.substringAfterLast('.', "").lowercase()
                        if (extension !in setOf("pdf", "jpg", "jpeg", "png", "webp", "txt", "md", "rtf", "docx"))
                            throw IllegalStateException("Choose PDF, image or text files.")
                        val copy = File.createTempFile("studio_pick_", ".$extension", cacheDir)
                        try {
                            var size = 0L
                            (contentResolver.openInputStream(uri) ?: error("Could not read $name")).use { input ->
                                copy.outputStream().use { target ->
                                    val buffer = ByteArray(65536)
                                    var count = input.read(buffer)
                                    while (count != -1) {
                                        size += count
                                        if (size > 150L * 1024 * 1024) error("Files must be smaller than 150 MB.")
                                        target.write(buffer, 0, count)
                                        count = input.read(buffer)
                                    }
                                }
                            }
                            mapOf("name" to name, "path" to copy.absolutePath)
                        } catch (e: Exception) { copy.delete(); throw e }
                    }
                } else if(requestCode==imageCode){
                    val uri=data?.data ?: throw IllegalStateException("No image selected.")
                    val input=contentResolver.openInputStream(uri) ?: throw IllegalStateException("Could not read photo.")
                    val dataBytes=ByteArrayOutputStream()
                    input.use { val buffer=ByteArray(8192);var count=it.read(buffer)
                        while(count!=-1){if(dataBytes.size()+count>12*1024*1024)throw IllegalStateException("Choose a photo smaller than 12 MB.");dataBytes.write(buffer,0,count);count=it.read(buffer)}
                    }
                    val bytes=dataBytes.toByteArray()
                    if(bytes.size>12*1024*1024)throw IllegalStateException("Choose a photo smaller than 12 MB.")
                    val options=BitmapFactory.Options().apply{inJustDecodeBounds=true}
                    BitmapFactory.decodeByteArray(bytes,0,bytes.size,options)
                    if(options.outWidth<=0||options.outHeight<=0)throw IllegalStateException("Choose a JPEG, PNG or WebP photo.")
                    options.inSampleSize=1
                    while(maxOf(options.outWidth,options.outHeight)/options.inSampleSize>1600)options.inSampleSize*=2
                    options.inJustDecodeBounds=false
                    var bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.size,options) ?: throw IllegalStateException("Photo could not be decoded.")
                    val rotation=try { val exif=ExifInterface(bytes.inputStream()); when(exif.getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL)) {
                        ExifInterface.ORIENTATION_ROTATE_90->90f;ExifInterface.ORIENTATION_ROTATE_180->180f;ExifInterface.ORIENTATION_ROTATE_270->270f;else->0f
                    }}catch(e:Exception){0f}
                    if(rotation!=0f){val rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.width,bitmap.height,Matrix().apply{postRotate(rotation)},true);if(rotated!==bitmap)bitmap.recycle();bitmap=rotated}
                    val output=ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,88,output);bitmap.recycle()
                    response=mapOf("name" to "hyzen_photo.jpg","bytes" to output.toByteArray())
                } else {
                    val uris = mutableListOf<Uri>()
                    val clips = data?.clipData
                    if (clips != null) {
                        if (clips.itemCount > 20) throw IllegalStateException("Choose at most 20 CSV files.")
                        for (i in 0 until clips.itemCount) uris.add(clips.getItemAt(i).uri)
                    } else data?.data?.let { uris.add(it) }
                    response = uris.map { uri ->
                        val name = fileName(uri)
                        if (!dataSelection && !name.endsWith(".csv", ignoreCase = true)) throw IllegalStateException("Choose CSV files only.")
                        val stream = contentResolver.openInputStream(uri) ?: throw IllegalStateException("Could not read $name.")
                        val bytes = ByteArrayOutputStream()
                        stream.use {
                            val buffer = ByteArray(8192)
                            var count = it.read(buffer)
                            while (count != -1) {
                                if (bytes.size() + count > 4 * 1024 * 1024) throw IllegalStateException("Each CSV must be 4 MB or smaller.")
                                bytes.write(buffer, 0, count)
                                count = it.read(buffer)
                            }
                        }
                        mapOf("name" to name, "bytes" to bytes.toByteArray())
                    }
                }
                runOnUiThread {
                    if (pending === result) {
                        pending = null
                        templateText = null
        exportPath = null
                        result.success(response)
                    }
                }
            } catch (e: Exception) {
                runOnUiThread {
                    if (pending === result) finishError("file_io", e.message ?: "Could not process the selected file.")
                }
            }
        }
    }
    override fun onDestroy() {
        externalFiles?.close()
        studioPdfEngine?.close()
        documentScanner?.close()
        cameraCapture?.close()
        liveScanner?.close()
        pending?.error("interrupted", "File selection was interrupted. Please retry.", null)
        pending = null
        fileWorker.shutdown()
        super.onDestroy()
    }
    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        externalFiles?.receive(intent)
    }
}

