package com.hyzen.pharmd

import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.nio.ByteBuffer
import kotlin.math.abs

@RunWith(AndroidJUnit4::class)
class ScanDetectorTest {
    @Test fun stridedCroppedLumaRotatesWithoutReadingPadding(){
        val bytes=ByteArray(64){99}
        for(y in 0..3)for(x in 0..5)bytes[y*16+x*2]=(y*10+x).toByte()
        val actual=ScanDetector.sample(ByteBuffer.wrap(bytes),16,2,1,1,4,2,90,32)
        assertEquals(2,actual.width);assertEquals(4,actual.height)
        assertArrayEquals(byteArrayOf(21,11,22,12,23,13,24,14),actual.pixels)
    }
    @Test fun whiteAndDarkSkewedPagesProduceClockwiseNormalizedCorners(){
        val expected=listOf(.22,.13,.84,.2,.77,.88,.13,.78)
        val w=200;val h=240
        for(bright in listOf(true,false)){
            val pixels=ByteArray(w*h)
            for(y in 0 until h)for(x in 0 until w){
                val nx=x.toDouble()/(w-1);val ny=y.toDouble()/(h-1)
                val inside=(0..3).all{i->val j=(i+1)%4;(expected[j*2]-expected[i*2])*(ny-expected[i*2+1])-(expected[j*2+1]-expected[i*2+1])*(nx-expected[i*2])>=0}
                pixels[y*w+x]=(if(inside)if(bright)225 else 35 else if(bright)25 else 235).toByte()
            }
            val candidate=ScanDetector.detect(ScanDetector.Gray(pixels,w,h))
            assertNotNull(candidate);ScanPerspective.validate(candidate!!.corners)
            for(i in expected.indices)assertEquals(expected[i],candidate.corners[i],.025)
        }
    }
    @Test fun flatFramesAndFrameFillingBackgroundAreNotDocuments(){
        for(value in listOf(0,120,255))assertNull(ScanDetector.detect(ScanDetector.Gray(ByteArray(10000){value.toByte()},100,100)))
        val border=ByteArray(10000){if(it%100<50)220.toByte() else 20.toByte()}
        assertNull(ScanDetector.detect(ScanDetector.Gray(border,100,100)))
    }
    private val good=ScanDetector.Candidate(listOf(.2,.1,.8,.1,.8,.9,.2,.9),.75,210.0,180.0,.98)
    @Test fun autoNeedsStableTimeQualityAndPageRemovalBeforeRearming(){
        val gate=ScanStability()
        for(i in 0..4)assertFalse(gate.update(good,i*200L).ready)
        assertTrue(gate.update(good,1000).ready)
        gate.captured()
        for(i in 6..15)assertFalse(gate.update(good,i*200L).ready)
        for(i in 16..18)gate.update(null,i*200L)
        var ready=false
        for(i in 19..24)ready=gate.update(good,i*200L).ready
        assertTrue(ready)
    }
    @Test fun blurLowLightMotionAndTimestampGapsPreventAuto(){
        for(candidate in listOf(good.copy(sharpness=0.0),good.copy(exposure=10.0))){val gate=ScanStability();for(i in 0..20)assertFalse(gate.update(candidate,i*200L).ready)}
        val moving=ScanStability()
        for(i in 0..20){val delta=if(i%2==0).04 else -.04;assertFalse(moving.update(good.copy(corners=good.corners.map{it+delta}),i*200L).ready)}
        val gaps=ScanStability();for(i in 0..20)assertFalse(gaps.update(good,i*1000L).ready)
    }
    @Test fun reviewRedetectionLeavesDraftAndOriginalBytesUnchanged(){
        val context=androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val source=java.io.File.createTempFile("redetect_", ".png",context.cacheDir)
        val image=android.graphics.Bitmap.createBitmap(400,500,android.graphics.Bitmap.Config.ARGB_8888)
        image.eraseColor(android.graphics.Color.BLACK)
        val path=android.graphics.Path().apply{moveTo(80f,50f);lineTo(340f,80f);lineTo(310f,450f);lineTo(40f,400f);close()}
        android.graphics.Canvas(image).drawPath(path,android.graphics.Paint().apply{color=android.graphics.Color.WHITE})
        source.outputStream().use{image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,it)};image.recycle()
        try {
            val pages=store.add(listOf(source.path));val raw=java.io.File(store.originalInfo(pages[0]).getValue("path"));val before=raw.readBytes()
            val corners=store.redetect(pages[0]);assertNotNull(corners);assertEquals(8,corners!!.size)
            assertEquals(pages,store.pages());assertArrayEquals(before,raw.readBytes())
        } finally{source.delete();store.clear()}
    }
}

package com.hyzen.pharmd

import android.Manifest
import android.graphics.BitmapFactory
import android.widget.Button
import android.view.View
import android.view.ViewGroup
import androidx.test.core.app.ActivityScenario
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

/** Emulated rear camera only. This is capture/durability integration, not phone quality evidence. */
@RunWith(AndroidJUnit4::class)
class LiveCameraTest {
    private fun buttons(view:View):List<Button> = if(view is ViewGroup)(0 until view.childCount).flatMap{buttons(view.getChildAt(it))} else if(view is Button)listOf(view) else emptyList()
    @Test fun manualCameraCaptureCommitsOriginalAndExportsReadablePage(){
        val instrumentation=InstrumentationRegistry.getInstrumentation();val context=instrumentation.targetContext
        instrumentation.uiAutomation.grantRuntimePermission(context.packageName,Manifest.permission.CAMERA)
        val store=ScanDraftStore(context);store.clear()
        var pdf:File?=null
        val captureMs=mutableListOf<Long>();val pssKiB=mutableListOf<Int>()
        try{
            ActivityScenario.launch(HyzenScanActivity::class.java).use{scenario->
                fun waitFor(label:String,timeout:Long=25000):Boolean {
                    var ready=false;val deadline=android.os.SystemClock.elapsedRealtime()+timeout
                    while(!ready&&android.os.SystemClock.elapsedRealtime()<deadline){
                        scenario.onActivity{activity->ready=buttons(activity.window.decorView).any{it.text==label&&it.isEnabled}}
                        if(!ready)Thread.sleep(100)
                    }
                    return ready
                }
                for(index in 1..5){
                    if(index==3)scenario.onActivity{it.requestedOrientation=android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE}
                    assertTrue("Emulated rear camera did not bind for page $index",waitFor("Capture"))
                    val started=android.os.SystemClock.elapsedRealtime()
                    scenario.onActivity{activity->
                        val shutter=buttons(activity.window.decorView).first{it.text=="Capture"}
                        shutter.performClick();assertFalse("Shutter must reject a rapid second capture",shutter.isEnabled)
                    }
                    assertTrue("Capture did not commit page $index",waitFor("Review ($index)",20000))
                    captureMs.add(android.os.SystemClock.elapsedRealtime()-started);pssKiB.add(android.os.Debug.getPss())
                    if(index==2||index==5)instrumentation.uiAutomation.takeScreenshot()?.let{bitmap->
                        val name=if(index==2)"qa_live_camera_portrait.png" else "qa_live_camera.png"
                        File(context.cacheDir,name).outputStream().use{bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,it)};bitmap.recycle()
                    }
                }
                scenario.onActivity{activity->assertTrue(buttons(activity.window.decorView).any{it.text=="Other scanner"})}
            }
            val metrics=org.json.JSONObject().put("environment","Android emulator; native Activity only, Flutter host not open").put("model",android.os.Build.MODEL).put("sdk",android.os.Build.VERSION.SDK_INT)
                .put("pages",5).put("capture_to_draft_ms",org.json.JSONArray(captureMs)).put("process_pss_kib",org.json.JSONArray(pssKiB))
                .put("physical_camera_acceptance",false).put("preview_fps_measured",false)
            File(context.cacheDir,"qa_camera_metrics.json").writeText(metrics.toString(2))
            val pages=ScanDraftStore(context).recover();assertEquals(5,pages.size)
            val original=File(store.originalInfo(pages[0]).getValue("path"));assertTrue(original.length()>0)
            val hashes=pages.map{java.security.MessageDigest.getInstance("SHA-256").digest(File(store.originalInfo(it).getValue("path")).readBytes())};val bounds=BitmapFactory.Options().apply{inJustDecodeBounds=true};BitmapFactory.decodeFile(original.path,bounds)
            assertTrue(bounds.outWidth>0&&bounds.outHeight>0)
            pdf=File(store.exportPdf(pages,false))
            com.tom_roush.pdfbox.pdmodel.PDDocument.load(pdf).use{assertEquals(5,it.numberOfPages)}
            pages.forEachIndexed{index,path->assertArrayEquals(hashes[index],java.security.MessageDigest.getInstance("SHA-256").digest(File(store.originalInfo(path).getValue("path")).readBytes()))}
        }finally{pdf?.delete();store.clear()}
    }
}

