import 'package:flutter/material.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../../core/utils/media_upload.dart';
import '../../../core/widgets/common.dart';
import '../../downloads/domain/download_record.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_file_item.dart';

/// Reached only after readable PDF validation, history import and editable backup.
class ScanSavedScreen extends ConsumerStatefulWidget {
  const ScanSavedScreen({super.key, required this.fileId});
  final String fileId;
  @override
  ConsumerState<ScanSavedScreen> createState() => _ScanSavedScreenState();
}

class _ScanSavedScreenState extends ConsumerState<ScanSavedScreen> {
  bool _busy = false;
  String? _verifiedPath;
  Future<bool>? _exists;
  Future<void> _action(Future<bool> Function() action, {bool device = false}) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      final completed = await action();
      if (mounted && device) showHSnack(context, completed ? 'PDF copy saved to your device' : 'Save cancelled. Your workspace PDF is still saved.');
      if (mounted && !device && !completed) showHSnack(context, 'Share was not opened. Your PDF is still saved.', error: true);
    } catch (_) {
      if (mounted) showHSnack(context, 'Could not finish. Your saved workspace PDF is safe; please retry.', error: true);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }
  @override
  Widget build(BuildContext context) {
    StudioFileItem? file;
    for (final item in ref.watch(pdfStudioHistoryProvider)) {
      if (item.id == widget.fileId) file = item;
    }
    final active = file;
    if (active != null && _verifiedPath != active.internalFilePath) {
      _verifiedPath = active.internalFilePath;
      _exists = ref.read(studioStorageProvider).exists(active.internalFilePath);
    }
    return Scaffold(
      appBar: AppBar(title: const Text('Scan saved'), leading: IconButton(tooltip: 'PDF Studio', icon: const Icon(Icons.arrow_back_rounded), onPressed: _busy ? null : () => context.go('/pdf-studio'))),
      body: active == null ? const EmptyState(icon: Icons.find_in_page_outlined, title: 'Saved scan not found', message: 'Open PDF Studio to check your workspace.') : FutureBuilder<bool>(
        future: _exists,
        builder: (context, snapshot) {
          if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator());
          if (snapshot.data != true) return const EmptyState(icon: Icons.error_outline, title: 'Workspace file unavailable', message: 'The file may have been moved or removed. Check PDF Studio before trying again.');
          return Center(child: SingleChildScrollView(padding: const EdgeInsets.all(24), child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 460), child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Icon(Icons.check_circle_rounded, size: 72, color: Theme.of(context).colorScheme.primary),
              const SizedBox(height: 20),
              Text('Your PDF is ready', textAlign: TextAlign.center, style: Theme.of(context).textTheme.headlineSmall),
              const SizedBox(height: 12),
              Text(active.displayName, textAlign: TextAlign.center, style: Theme.of(context).textTheme.titleMedium),
              const SizedBox(height: 8),
              Text('${active.pageCount} ${active.pageCount == 1 ? 'page' : 'pages'} · ${formatBytes(active.fileSizeBytes)}', textAlign: TextAlign.center),
              const SizedBox(height: 16),
              Text(!kIsWeb && defaultTargetPlatform == TargetPlatform.android ? 'Saved in your workspace. Editable scan originals are kept so you can make another copy later.' : 'Saved in your workspace. You can open, share or save a copy to your device.', textAlign: TextAlign.center),
              const SizedBox(height: 28),
              FilledButton.icon(onPressed: _busy ? null : () => context.replace('/pdf-studio/viewer/${active.id}'), icon: const Icon(Icons.picture_as_pdf_outlined), label: const Text('Open PDF')),
              const SizedBox(height: 12),
              OutlinedButton.icon(onPressed: _busy ? null : () => _action(() => MediaUpload.shareDocument(active.internalFilePath, active.displayName, 'application/pdf')), icon: const Icon(Icons.ios_share_rounded), label: const Text('Share PDF')),
              const SizedBox(height: 12),
              OutlinedButton.icon(onPressed: _busy ? null : () => _action(() => MediaUpload.exportPdf(active.internalFilePath, active.displayName), device: true), icon: const Icon(Icons.save_alt_rounded), label: const Text('Save copy to device')),
              const SizedBox(height: 12),
              TextButton(onPressed: _busy ? null : () => context.go('/pdf-studio'), child: const Text('Back to PDF Studio')),
              if (_busy) const Padding(padding: EdgeInsets.all(12), child: LinearProgressIndicator()),
            ],
          ))));
        },
      ),
    );
  }
}

